import{_ as e}from"./chunks/00-sidebar-overview.Cutxsm52.js";import{_ as a}from"./chunks/12-audit.hDds1b_-.js";import{_ as r,o as s,c as o,a2 as i}from"./chunks/framework.D4up2k3b.js";const _=JSON.parse('{"title":"安全与敏感文件","description":"","frontmatter":{},"headers":[],"relativePath":"features/security.md","filePath":"features/security.md","lastUpdated":1791393728000}'),n={name:"features/security.md"};function l(d,t,h,c,p,u){return s(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="安全与敏感文件" tabindex="-1">安全与敏感文件 <a class="header-anchor" href="#安全与敏感文件" aria-label="Permalink to &quot;安全与敏感文件&quot;">​</a></h1><p>filebox 的默认姿态是：<strong>浏览只读、路径牢笼、敏感文件拒绝</strong>。两个写能力（Transfer、Terminal）是显式例外，且默认需要能力开启 / 本地配置。</p><p><img src="'+e+`" alt="侧栏能力入口"></p><h2 id="只读协议" tabindex="-1">只读协议 <a class="header-anchor" href="#只读协议" aria-label="Permalink to &quot;只读协议&quot;">​</a></h2><p>浏览路径没有写 / 删 / 重命名 / 任意 exec 消息。</p><table tabindex="0"><thead><tr><th>例外</th><th>作用域</th><th>防护</th></tr></thead><tbody><tr><td><strong>Transfer</strong></td><td>仅 Agent 专用 scratch 目录</td><td>配额、禁覆盖、不作为普通 root</td></tr><tr><td><strong>Terminal</strong></td><td>Agent 本机 shell（<strong>非沙箱</strong>）</td><td>Agent 本地 TOTP；密钥不进 Hub</td></tr></tbody></table><h2 id="敏感文件默认拒绝-节选" tabindex="-1">敏感文件默认拒绝（节选） <a class="header-anchor" href="#敏感文件默认拒绝-节选" aria-label="Permalink to &quot;敏感文件默认拒绝（节选）&quot;">​</a></h2><p>即使根目录已授权，匹配项仍不可读：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.git/  .ssh/  .gnupg/  .aws/  .kube/</span></span>
<span class="line"><span>.env*  *.pem  *.key  id_*  credentials*.json  *.sqlite*</span></span></code></pre></div><p>以及 shell history 等常见凭证位置。具体规则以当前版本实现为准。</p><h2 id="路径牢笼" tabindex="-1">路径牢笼 <a class="header-anchor" href="#路径牢笼" aria-label="Permalink to &quot;路径牢笼&quot;">​</a></h2><p>浏览严格限制在已添加的 root 内；<code>..</code>、符号链接逃逸等会被挡住。</p><h2 id="认证与信任" tabindex="-1">认证与信任 <a class="header-anchor" href="#认证与信任" aria-label="Permalink to &quot;认证与信任&quot;">​</a></h2><ul><li>用户登录在 Hub（PoW + 会话 cookie + CSRF）。</li><li>每台机器用独立 Agent token（Hub 只存 hash）。</li><li>Agent 出站连 Hub；目标机无需入站。</li><li>生产环境务必 HTTPS，保护 token 与会话。</li><li>登录事件见侧栏 <strong>Audit</strong>。</li></ul><p><img src="`+a+'" alt="登录审计"></p><h2 id="架构向说明" tabindex="-1">架构向说明 <a class="header-anchor" href="#架构向说明" aria-label="Permalink to &quot;架构向说明&quot;">​</a></h2><p>更底层的 Hub↔Agent 信任边界、token、限流等见仓库内开发文档 <a href="https://github.com/ZhimingYe/filebox/blob/main/docs/hub-agent-security-model.md" target="_blank" rel="noreferrer"><code>docs/hub-agent-security-model.md</code></a>（中文）。</p>',17)])])}const f=r(n,[["render",l]]);export{_ as __pageData,f as default};
